package com.kj.steady;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.net.Uri;import android.util.Base64;import java.io.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 WebView web; String pending;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff122b27);getWindow().setNavigationBarColor(0xff122b27);web=new WebView(this);setContentView(web);web.setPadding(0,0,0,0);web.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&"app.local".equals(u.getHost())){String p=u.getPath();if(p==null||p.contains(".."))return empty();try{String name=p.equals("/")?"index.html":p.substring(1);String mime=name.endsWith(".js")?"application/javascript":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open(name));}catch(Exception e){return empty();}}return empty();}private WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});web.setWebChromeClient(new WebChromeClient(){ public boolean onJsConfirm(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("Continue",(d,w)->result.confirm()).setNegativeButton("Cancel",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});web.loadUrl("https://app.local/");}
 class Bridge {
 @JavascriptInterface public String load(){return getSharedPreferences("tracker",0).getString("data","");}
 @JavascriptInterface public boolean save(String s){if(s.length()>2000000)return false;return getSharedPreferences("tracker",0).edit().putString("data",s).commit();}
 @JavascriptInterface public void exportData(String s){if(s.length()>2000000)return;pending=s;runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"KJ-Steady-backup-"+new java.text.SimpleDateFormat("yyyy-MM-dd").format(new java.util.Date())+".json");startActivityForResult(i,1);});}
 @JavascriptInterface public void importData(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,2);});}
 }
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;try{if(request==1&&pending!=null){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(pending.getBytes(StandardCharsets.UTF_8));}pending=null;web.evaluateJavascript("toast('Backup saved')",null);}else if(request==2){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(data.getData())){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>2000000)throw new IOException();}}String encoded=Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);web.evaluateJavascript("receiveBackup('"+encoded+"')",null);}}catch(Exception e){web.evaluateJavascript("toast('Could not read or save file. Try again.')",null);}}
 @Override public void onBackPressed(){web.evaluateJavascript("showTab('today')",null);}
}
